  return `${htmlOpen(environment, title)}<meta http-equiv="Content-Security-Policy" content="${escapeHTML(policy)}"><meta http-equiv="Content-Security-Policy" content="${escapeHTML(scriptPolicy)}"><meta name="referrer" content="no-referrer"><meta name="viewport" content="width=device-width,initial-scale=1">${stylesHref ? `<link rel="stylesheet" href="${escapeHTML(stylesHref)}">` : ''}<style>${stylesHref ? '' : inlineStyle(styles)}\n${baseStyles(environment)}</style><style>${inlineStyle(compiled.css)}</style><title>${escapeHTML(title)}</title></head><body><div id="hawiyah-preview-root"></div>${runtimeSrc ? `<script nonce="${nonce}" src="${escapeHTML(runtimeSrc)}"></script>` : `<script nonce="${nonce}">${inlineScript(runtime)}</script>`}${bootstrap(payload, 'startBundled', nonce)}</body></html>`;
}

/**
 * (b) Published files. Scripts, styles, fonts and images may come only from `runtimeBase` (one directory
 * of immutable, versioned files) or from data: URLs created by the parent for the edited project.
 * `allowEval` is needed by Angular JIT and by Vue's runtime template compiler, never otherwise.
 */
export function modulesDocument({ framework, compiled, host, importmap, runtimeBase, stylesHref, inlineStyles = '', preload = [], allowEval = false, angularDevMode = false, bare = false, environment, token, run, title = 'Hawiyah example', labels = defaultLabels }) {
  const nonce = newNonce(), unsafeEval = allowEval ? " 'unsafe-eval'" : '';
  const policy = `default-src 'none'; script-src 'nonce-${nonce}' ${runtimeBase} data:${unsafeEval}; style-src 'unsafe-inline' ${runtimeBase}; img-src data: blob: ${runtimeBase}; font-src data: ${runtimeBase}; media-src data: blob:; connect-src 'none'; frame-src 'none'; object-src 'none'; worker-src 'none'; base-uri 'none'; form-action 'none'`;
  // Without this second policy a nonce-bearing script could import() any URL, because imports inherit the nonce.
  const scriptPolicy = `script-src 'unsafe-inline' ${runtimeBase} data:${unsafeEval}`;
  const imports = { ...importmap.imports };
  for (const [name, code] of Object.entries(compiled.modules)) imports[`hawiyah-project/${name}`] = moduleDataURL(`${code}\n//# sourceURL=hawiyah-project/${name}`);
  const payload = { channel, token, run, nonce, framework, html: host, entry: compiled.entry, labels };
  // Order matters: the bootstrap precedes the stylesheet so the stylesheet cannot block it, and the import map precedes every import.
  return `${htmlOpen(environment, title)}<meta http-equiv="Content-Security-Policy" content="${escapeHTML(policy)}"><meta http-equiv="Content-Security-Policy" content="${escapeHTML(scriptPolicy)}"><meta name="referrer" content="no-referrer"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(title)}</title><script type="importmap" nonce="${nonce}">${embeddedJSON({ imports })}</script>${preload.map(href => `<link rel="modulepreload" href="${escapeHTML(href)}">`).join('')}${framework === 'angular' && !angularDevMode ? `<script nonce="${nonce}">globalThis.ngDevMode=false;</script>` : ''}${bootstrap(payload, 'startModules', nonce)}${stylesHref ? `<link rel="stylesheet" href="${escapeHTML(stylesHref)}">` : ''}<style>${inlineStyle(inlineStyles)}\n${(bare ? bareStyles : baseStyles)(environment)}</style><style>${inlineStyle(compiled.css)}</style></head><body><div id="hawiyah-preview-root"></div></body></html>`;
}

