import { Component, ElementRef, OnDestroy, afterNextRender, effect, inject, input, untracked, viewChild } from '@angular/core';
import { EditorState, Prec, type Extension } from '@codemirror/state';
import { EditorView, keymap } from '@codemirror/view';
import { HighlightStyle, syntaxHighlighting } from '@codemirror/language';
import { indentWithTab } from '@codemirror/commands';
import { basicSetup } from 'codemirror';
import { javascript } from '@codemirror/lang-javascript';
import { html } from '@codemirror/lang-html';
import { css } from '@codemirror/lang-css';
import { vue } from '@codemirror/lang-vue';
import { tags } from '@lezer/highlight';
import { EditorStore } from './store';

/** The editing engine keeps its own internal styling; every colour and size it uses is a Hawiyah token. */
const theme = EditorView.theme({
  '&': { color: 'var(--hw-color-text)', backgroundColor: 'var(--hw-color-surface)', fontSize: 'var(--hw-text-sm)', blockSize: '100%' },
  '&.cm-focused': { outline: 'var(--hw-focus-width) solid var(--hw-color-focus)', outlineOffset: 'calc(var(--hw-focus-width) * -1)' },
  '.cm-scroller': { fontFamily: 'var(--hw-font-mono)', lineHeight: '1.6', overflow: 'auto' },
  '.cm-content': { caretColor: 'var(--hw-color-text)', paddingBlock: 'var(--hw-space-3)' },
  '.cm-gutters': { backgroundColor: 'var(--hw-color-surface-muted)', color: 'var(--hw-color-text-muted)', border: '0', borderInlineEnd: '1px solid var(--hw-color-border)' },
  '.cm-activeLine': { backgroundColor: 'transparent' },
  '.cm-activeLineGutter': { backgroundColor: 'var(--hw-color-surface-muted)', color: 'var(--hw-color-text)' },
  '.cm-cursor, .cm-dropCursor': { borderInlineStartColor: 'var(--hw-color-text)' },
  '&.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground, .cm-selectionBackground, .cm-content ::selection': { backgroundColor: 'var(--hw-color-primary-subtle)' },
  '.cm-matchingBracket, &.cm-focused .cm-matchingBracket': { backgroundColor: 'var(--hw-color-primary-subtle)', outline: '1px solid var(--hw-color-border-strong)' },
  '.cm-selectionMatch': { backgroundColor: 'var(--hw-color-surface-muted)' },
  '.cm-panels': { backgroundColor: 'var(--hw-color-surface-muted)', color: 'var(--hw-color-text)', borderColor: 'var(--hw-color-border)' },
  '.cm-tooltip': { backgroundColor: 'var(--hw-color-surface-raised)', color: 'var(--hw-color-text)', border: '1px solid var(--hw-color-border)', borderRadius: 'var(--hw-radius-sm)' },
  '.cm-foldPlaceholder': { backgroundColor: 'var(--hw-color-surface-muted)', color: 'var(--hw-color-text-muted)', border: '1px solid var(--hw-color-border)' },
});
const highlight = HighlightStyle.define([
  { tag: [tags.keyword, tags.modifier, tags.operatorKeyword, tags.definitionKeyword], color: 'var(--hw-color-primary-text)', fontWeight: '500' },
  { tag: [tags.string, tags.special(tags.string), tags.attributeValue], color: 'var(--hw-color-badge-success-text)' },
  { tag: [tags.number, tags.bool, tags.null, tags.atom], color: 'var(--hw-color-badge-warning-text)' },
  { tag: [tags.comment, tags.meta], color: 'var(--hw-color-text-muted)', fontStyle: 'italic' },
  { tag: [tags.typeName, tags.className, tags.tagName, tags.namespace], color: 'var(--hw-color-badge-info-text)' },
  { tag: [tags.attributeName, tags.propertyName], color: 'var(--hw-color-text)' },
  { tag: tags.invalid, color: 'var(--hw-color-field-error-text)' },
]);
const languageOf = (file: string): Extension => file.endsWith('.html') ? html() : file.endsWith('.css') ? css() : file.endsWith('.vue') ? vue() : javascript({ jsx: /\.[jt]sx$/.test(file), typescript: /\.tsx?$/.test(file) });

/**
 * The code editing surface: CodeMirror 6 behind one boundary. Always left to right, whatever the page direction.
 * Tab indents. Escape followed by Tab (or Shift+Tab) moves focus out of the editor: CodeMirror leaves the next
 * Tab unhandled for two seconds after Escape. Ctrl/Cmd+Enter runs the example and inserts nothing.
 */
@Component({ selector: 'app-code-surface',
  template: `<div #host class="surface" dir="ltr" lang="en"></div>`,
  styles: `:host { display: block; min-block-size: 0; min-inline-size: 0; } .surface { block-size: 100%; min-block-size: inherit; direction: ltr; text-align: start; }` })
export class CodeSurface implements OnDestroy {
  readonly store = inject(EditorStore);
  readonly label = input.required<string>();
  readonly describedBy = input('');
  readonly readOnly = input(false);
  private readonly host = viewChild.required<ElementRef<HTMLElement>>('host');
  private view?: EditorView;
  private key = '';
  private tick = this.store.resetTick();

  constructor() {
    afterNextRender(() => {
      this.view = new EditorView({ parent: this.host().nativeElement });
      // Handle for the prototype's behaviour checks (tools/verify.cjs).
      (this.host().nativeElement as HTMLElement & { editorView?: EditorView }).editorView = this.view;
      this.sync(this.store.docKey());
    });
    effect(() => { const key = this.store.docKey(); this.store.example(); untracked(() => this.sync(key)); });
    effect(() => {
      const tick = this.store.resetTick();
      if (tick === this.tick) return;
      this.tick = tick;
      const view = this.view, original = untracked(() => this.store.example()?.files[this.store.activeFile()]);
      if (view && original !== undefined && view.state.doc.toString() !== original) view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: original } });
    });
  }

  private sync(key: string): void {
    const view = this.view, store = this.store;
    if (!view || !key) return;
    if (this.key && this.key !== key) store.editorStates.set(this.key, view.state);
    if (this.key === key) return;
    this.key = key;
    // A read-only view never reuses or stores an editable state.
    view.setState((this.readOnly() ? undefined : store.editorStates.get(key)) ?? this.create(key, store.source(store.activeFile()), store.activeFile()));
  }
  private create(key: string, doc: string, file: string): EditorState {
    const run = () => { void this.store.run(); return true; };
    return EditorState.create({ doc, extensions: [
      // Before the default keymap, so Ctrl/Cmd+Enter never reaches insertBlankLine.
      Prec.highest(keymap.of([{ key: 'Mod-Enter', run, preventDefault: true }])),
      basicSetup, keymap.of([indentWithTab]), languageOf(file), theme, syntaxHighlighting(highlight), EditorView.lineWrapping,
      EditorState.readOnly.of(this.readOnly()), EditorView.editable.of(!this.readOnly()),
      EditorView.contentAttributes.of({ 'aria-label': this.label(), 'aria-describedby': this.describedBy(), dir: 'ltr', lang: 'en', tabindex: '0', ...(this.readOnly() ? { 'aria-readonly': 'true' } : {}) }),
      EditorView.updateListener.of(update => { if (update.docChanged && !this.readOnly()) this.store.setDraft(key, update.state.doc.toString()); }),
    ] });
  }
  ngOnDestroy(): void {
    if (this.view && this.key && !this.readOnly()) this.store.editorStates.set(this.key, this.view.state);
    this.view?.destroy();
  }
}

