import { NgTemplateOutlet } from '@angular/common';
import { Component, DOCUMENT, OnDestroy, computed, effect, inject, signal } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { HwAlertComponent, HwButtonDirective, HwCollapsibleComponent, HwTabComponent, HwTabsComponent, HwTreeViewComponent } from '@hawiyah/angular';
import { CodeSurface } from './code-surface';
import { EditorStatus, FileActions, FileSwitch, FrameworkSwitch, LanguageSwitch, LogPanel, PageFrame, Result, RunButton, RunState, narrowViewport, shell } from './parts';
import { EditorStore, frameworkNames, frameworks, type Framework } from './store';

abstract class EditorPage {
  readonly store = inject(EditorStore);
  readonly frameworks = frameworks;
  readonly names = frameworkNames;
  readonly hintId = EditorStatus.hintId;
  readonly narrow = narrowViewport();
  readonly more = computed(() => this.t('More tabs', 'المزيد من التبويبات'));
  readonly choice = computed(() => `${frameworkNames[this.store.framework()]} · ${this.store.language() === 'ts' ? 'TypeScript' : 'JavaScript'}`);
  t(en: string, ar: string) { return this.store.prefs.t(en, ar); }
  codeLabel(file: string) { return this.t(`Code of ${file}`, `شيفرة الملف ${file}`); }
}

/**
 * A. One toolbar: every control in one row, file tabs over the code, code and result side by side, a thin status bar.
 * On a phone the two segmented controls fold into one disclosure and the result comes directly under the toolbar,
 * next to the Run button that produces it.
 */
@Component({ selector: 'app-editor-a', imports: [PageFrame, CodeSurface, EditorStatus, FileActions, FrameworkSwitch, LanguageSwitch, LogPanel, Result, RunButton, HwTabsComponent, HwTabComponent, HwCollapsibleComponent, HwButtonDirective, RouterLink, NgTemplateOutlet],
  template: `
  <app-page-frame [wide]="workspace" [heading]="workspace ? t('Live editor', 'المحرر المباشر') : ''" [lede]="workspace ? t('Example: request form, from the Text field page. Drafts are kept in this browser for each framework and language.', 'المثال: نموذج طلب، من صفحة الحقل النصي. تُحفظ المسودات في هذا المتصفح لكل إطار عمل ولغة برمجية.') : ''" [sectionTitle]="workspace ? t('Request form', 'نموذج طلب') : ''">
    @if (workspace) { <p class="back"><a hwButton variant="link" size="sm" routerLink="/editor/d" queryParamsHandling="preserve">{{ t('Back to the Text field page', 'العودة إلى صفحة الحقل النصي') }}</a></p> }
    <ng-template #code>
      <div class="ed-pane ed-code">
        <hw-tabs [label]="t('Files', 'الملفات')" [value]="store.activeFile()" (valueChange)="store.setFile($event)" [overflowLabel]="more()">
          @for (file of store.files(); track file) { <hw-tab [value]="file" [label]="file">@if (store.activeFile() === file) { <app-code-surface [label]="codeLabel(file)" [describedBy]="hintId" /> }</hw-tab> }
        </hw-tabs>
      </div>
    </ng-template>
    <ng-template #result>
      <div class="ed-pane side">
        <h3 class="ed-pane-title">{{ t('Result', 'النتيجة') }}</h3>
        <app-result />
        @if (workspace) { <div class="log"><app-log-panel /></div> }
        @else if (store.logs().length) { <div class="fold"><hw-collapsible [label]="t('Log', 'السجل') + ' (' + store.logs().length + ')'"><app-log-panel [heading]="false" /></hw-collapsible></div> }
      </div>
    </ng-template>
    <div class="ed-shell" [class.workspace]="workspace">
      <div class="ed-bar" role="group" [attr.aria-label]="t('Editor controls', 'عناصر التحكم في المحرر')">
        @if (narrow()) { <div class="choice"><hw-collapsible [label]="choice()"><div class="switches"><app-framework-switch /><app-language-switch /></div></hw-collapsible></div> }
        @else { <app-framework-switch /><app-language-switch /><span class="ed-grow"></span> }
        <app-file-actions /><span class="ed-grow"></span><app-run-button />
      </div>
      <div class="panes">
        @if (narrow()) { <ng-container [ngTemplateOutlet]="result" /><ng-container [ngTemplateOutlet]="code" /> }
        @else { <ng-container [ngTemplateOutlet]="code" /><ng-container [ngTemplateOutlet]="result" /> }
      </div>
      <app-editor-status />
    </div>
  </app-page-frame>`,
  styles: [shell, `
    .panes { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); min-inline-size: 0; }
    .side { display: grid; grid-template-rows: auto auto minmax(0, 1fr); align-content: start; border-inline-start: 1px solid var(--hw-color-border); }
    .workspace .ed-code { --ed-code-block: clamp(22rem, calc(100dvh - 29rem), 52rem); }
    .log { align-self: end; block-size: 12rem; border-block-start: 1px solid var(--hw-color-border); display: grid; }
    .fold { padding: var(--hw-space-3); align-self: end; }
    .back { margin-block: 0 var(--hw-space-3); }
    .choice { flex: 1 1 100%; min-inline-size: 0; } .switches { display: grid; gap: var(--hw-space-3); }
    @media (max-width: 56rem) {
      .panes { grid-template-columns: minmax(0, 1fr); }
      .side { border-inline-start: 0; border-block-end: 1px solid var(--hw-color-border); }
      .ed-code, .workspace .ed-code { --ed-code-block: clamp(16rem, 60dvh, 30rem); }
    }`] })
export class EditorA extends EditorPage { readonly workspace = inject(ActivatedRoute).snapshot.data['workspace'] === true; }

/** B. Preview first: the result on top, the code in a collapsible panel with framework tabs. */
@Component({ selector: 'app-editor-b', imports: [PageFrame, CodeSurface, EditorStatus, FileActions, FileSwitch, LanguageSwitch, LogPanel, Result, RunButton, RunState, HwTabsComponent, HwTabComponent, HwCollapsibleComponent],
  template: `
  <app-page-frame>
    <div class="ed-shell preview" [class.pinned]="open()">
      <div class="ed-pane view"><h3 class="ed-pane-title">{{ t('Result', 'النتيجة') }}</h3><app-result /></div>
      <app-editor-status [readOnly]="!open()" />
    </div>
    <div class="code">
      <hw-collapsible [label]="t('Code', 'الشيفرة') + ': ' + choice()" [open]="open()" (openChange)="setOpen($event)">
        @if (open()) {
          <hw-tabs [label]="t('Framework', 'إطار العمل')" [value]="store.framework()" (valueChange)="store.setFramework($any($event))" [overflowLabel]="more()">
            @for (framework of frameworks; track framework) { <hw-tab [value]="framework" [label]="names[framework]">@if (store.framework() === framework) {
              <div class="row" role="group" [attr.aria-label]="t('Editor controls', 'عناصر التحكم في المحرر')"><app-language-switch /><app-file-switch /><span class="ed-grow"></span><app-file-actions /><app-run-state /><app-run-button /></div>
              <div class="ed-code frame"><app-code-surface [label]="codeLabel(store.activeFile())" [describedBy]="hintId" /></div>
              @if (store.logs().length) { <div class="frame log"><app-log-panel /></div> }
            }</hw-tab> }
          </hw-tabs>
        }
      </hw-collapsible>
    </div>
  </app-page-frame>`,
  styles: [shell, `
    .code { margin-block-start: var(--hw-space-4); min-inline-size: 0; }
    .row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--hw-space-2) var(--hw-space-3); margin-block-end: var(--hw-space-3); padding-inline: var(--hw-space-0-5); }
    .frame { border: 1px solid var(--hw-color-border); border-radius: var(--hw-radius-sm); overflow: clip; }
    .ed-code { --ed-code-block: clamp(18rem, 56dvh, 34rem); }
    .log { margin-block-start: var(--hw-space-3); max-block-size: 12rem; display: grid; }
    /* With the code open on a large screen the result stays in view while the code scrolls under it. */
    @media (min-width: 56rem) and (min-height: 48rem) {
      .pinned { position: sticky; inset-block-start: var(--hw-space-2); z-index: var(--hw-z-sticky); }
      .pinned .view { max-block-size: 42dvh; overflow: auto; }
    }`] })
export class EditorB extends EditorPage {
  private readonly view = inject(DOCUMENT).defaultView;
  /** Closed on a first visit; the choice is remembered. ?code=open opens it (used for the captures). */
  readonly open = signal(new URLSearchParams(this.view?.location.search ?? '').get('code') === 'open' || this.recall() === '1');
  private recall() { try { return this.view?.localStorage.getItem('hw-prototype-editor:code'); } catch { return null; } }
  setOpen(open: boolean): void { this.open.set(open); try { this.view?.localStorage.setItem('hw-prototype-editor:code', open ? '1' : '0'); } catch { /* not remembered */ } }
}

/** C. Workspace: a project panel with frameworks and files as one tree, editor and result side by side, a log panel. */
@Component({ selector: 'app-editor-c', imports: [PageFrame, CodeSurface, EditorStatus, FileActions, LanguageSwitch, LogPanel, Result, RunButton, HwTreeViewComponent, HwCollapsibleComponent, NgTemplateOutlet],
  template: `
  <app-page-frame [wide]="true">
    <ng-template #project>
      <hw-tree-view [label]="t('Frameworks and files', 'أطر العمل والملفات')" [nodes]="nodes()" [value]="selected()" [expandedIds]="expanded()" (expandedIdsChange)="expanded.set($event)" (valueChange)="pick($event)" />
      <app-language-switch />
    </ng-template>
    <ng-template #result><div class="ed-pane result"><h3 class="ed-pane-title">{{ t('Result', 'النتيجة') }}</h3><app-result /></div></ng-template>
    <div class="ed-shell work">
      <div class="ed-bar top" role="group" [attr.aria-label]="t('Editor controls', 'عناصر التحكم في المحرر')">
        <p class="path"><bdi dir="ltr">{{ names[store.framework()] }} / {{ store.activeFile() }}</bdi></p><span class="ed-grow"></span><app-file-actions /><app-run-button />
      </div>
      @if (narrow()) {
        <ng-container [ngTemplateOutlet]="result" />
        <div class="fold"><hw-collapsible [label]="t('Project', 'المشروع') + ': ' + names[store.framework()] + ' / ' + store.activeFile()"><div class="tree"><ng-container [ngTemplateOutlet]="project" /></div></hw-collapsible></div>
      } @else { <aside class="ed-pane project" [attr.aria-label]="t('Project', 'المشروع')"><h3 class="ed-pane-title">{{ t('Project', 'المشروع') }}</h3><div class="tree"><ng-container [ngTemplateOutlet]="project" /></div></aside> }
      <div class="ed-pane ed-code editor"><app-code-surface [label]="codeLabel(store.activeFile())" [describedBy]="hintId" /></div>
      @if (!narrow()) { <ng-container [ngTemplateOutlet]="result" /> }
      <div class="ed-pane log"><app-log-panel /></div>
      <div class="status"><app-editor-status /></div>
    </div>
  </app-page-frame>`,
  styles: [shell, `
    .work { grid-template-columns: 15rem minmax(0, 1.1fr) minmax(0, 1fr); grid-template-rows: auto auto 11rem auto; }
    .top, .status { grid-column: 1 / -1; } .path { margin: 0; font-family: var(--hw-font-mono); font-size: var(--hw-text-sm); }
    .project { grid-row: 2 / 4; border-inline-end: 1px solid var(--hw-color-border); overflow: auto; }
    .tree { display: grid; gap: var(--hw-space-3); padding: 0 var(--hw-space-2) var(--hw-space-3); }
    .ed-code { --ed-code-block: clamp(20rem, calc(100dvh - 30rem), 44rem); }
    .result { border-inline-start: 1px solid var(--hw-color-border); overflow: auto; max-block-size: clamp(20rem, calc(100dvh - 30rem), 44rem); }
    .log { grid-column: 2 / -1; border-block-start: 1px solid var(--hw-color-border); display: grid; }
    .fold { padding: var(--hw-space-3); border-block-end: 1px solid var(--hw-color-border); }
    @media (max-width: 56rem) {
      .work { grid-template-columns: minmax(0, 1fr); grid-template-rows: none; }
      .result { border-inline-start: 0; border-block-end: 1px solid var(--hw-color-border); max-block-size: none; }
      .log { grid-column: 1; max-block-size: 14rem; }
      .ed-code { --ed-code-block: clamp(16rem, 56dvh, 28rem); }
      .tree { padding: 0; }
    }`] })
export class EditorC extends EditorPage {
  readonly expanded = signal<readonly string[]>([this.store.framework()]);
  readonly nodes = computed(() => frameworks.map(framework => ({ id: framework, label: frameworkNames[framework], children: this.store.fileNames(framework).map(file => ({ id: `${framework}:${file}`, label: file })) })));
