/**
 * Placement and the minimal token-only frame of the editor's panes. The packages have no panel, toolbar,
 * split-pane or status-bar component, so these are plain elements with a token border and surface.
 */
export const shell = `
  :host { display: block; min-inline-size: 0; }
  .ed-shell { display: grid; min-inline-size: 0; border: 1px solid var(--hw-color-border); border-radius: var(--hw-radius-md); background: var(--hw-color-surface); overflow: clip; }
  .ed-bar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--hw-space-2) var(--hw-space-3); min-inline-size: 0; padding: var(--hw-space-2) var(--hw-space-3); border-block-end: 1px solid var(--hw-color-border); }
  .ed-grow { flex: 1 1 0; min-inline-size: 0; }
  .ed-pane { min-inline-size: 0; min-block-size: 0; }
  .ed-pane-title { margin: 0; padding: var(--hw-space-2) var(--hw-space-3); font-size: var(--hw-text-sm); font-weight: var(--hw-weight-semibold); color: var(--hw-color-text-muted); }
  .ed-code { --ed-code-block: clamp(20rem, calc(100dvh - 25rem), 44rem); }
