`;

/** Viewport signal for the few places where the phone layout needs a different structure, not only different placement. */
export function narrowViewport(query = '(max-width: 56rem)') {
  const view = inject(DOCUMENT).defaultView, media = view?.matchMedia(query), narrow = signal(!!media?.matches);
  media?.addEventListener('change', event => narrow.set(event.matches));
  return narrow.asReadonly();
}

