/** Reset, copy and download. Text buttons: the published icon set has no reset, copy, download or run glyph. */
@Component({ selector: 'app-file-actions', imports: [HwButtonDirective],
  template: `
    @if (!readOnly()) { <button hwButton variant="ghost" size="sm" type="button" [disabled]="!store.dirty()" (click)="store.reset()">{{ t('Reset', 'استعادة الأصل') }}</button> }
    <button hwButton variant="ghost" size="sm" type="button" (click)="copy()">@if (copied()) { <span class="hw-icon" data-icon="tick-02" data-size="sm" aria-hidden="true"></span> }{{ copied() ? t('Copied', 'نُسخ') : t('Copy', 'نسخ') }}</button>
