  readonly readOnly = input(false);
  readonly copied = signal(false);
  t(en: string, ar: string) { return this.store.prefs.t(en, ar); }
  async copy(): Promise<void> {
    try { await this.doc.defaultView?.navigator.clipboard.writeText(this.store.source(this.store.activeFile())); this.copied.set(true); setTimeout(() => this.copied.set(false), 2000); } catch { /* clipboard unavailable */ }
  }
  /** Prototype: downloads the open file. The project archive of the current guide is not rebuilt here. */
  download(): void {
    const file = this.store.activeFile(), url = URL.createObjectURL(new Blob([this.store.source(file)], { type: 'text/plain;charset=utf-8' }));
    const link = this.doc.createElement('a');
    link.href = url; link.download = file; link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
}

