import { DOCUMENT, Injectable, computed, effect, inject, signal, untracked } from '@angular/core';
import { parser as javascriptParser } from '@lezer/javascript';
import type { EditorState } from '@codemirror/state';
import { Prefs } from '../prefs';

export type Framework = 'vanilla' | 'react' | 'vue' | 'angular';
export type Language = 'js' | 'ts';
export type RunState = 'idle' | 'running' | 'ready' | 'error';
export interface LogEntry { level: 'log' | 'info' | 'warn' | 'error'; text: string; }
export interface Example { framework: Framework; language: Language; locale: string; entry: string; host: string; order: string[]; files: Record<string, string>; compiled: unknown; }
export interface FrameDocument { srcdoc: string; token: string; run: number; }

export const frameworks: readonly Framework[] = ['vanilla', 'react', 'vue', 'angular'];
export const frameworkNames: Record<Framework, string> = { vanilla: 'JavaScript', react: 'React', vue: 'Vue', angular: 'Angular' };
const exampleId = 'request-form';
const storageKey = 'hw-prototype-editor:v1';
const compilerOf: Record<Framework, string> = { vanilla: 'sucrase', react: 'sucrase', vue: 'sucrase', angular: 'angular-jit' };
/** Text of the function that stops a loop which blocks the frame for more than two seconds. It lives inside the frame only. */
const loopGuard = "globalThis.__hwLoopGuard??=(()=>{let since=0,armed=false;return()=>{const now=performance.now();if(!armed){armed=true;since=now;setTimeout(()=>{armed=false;},0);}else if(now-since>2000)throw new Error('LOOP_GUARD');};})();";

/** Insert a guard call into every loop body of compiled JavaScript. Positions on a line change, line numbers do not. */
export function guardLoops(code: string): string {
  const tree = javascriptParser.parse(code);
  const inserts: { at: number; text: string }[] = [];
  let broken = false;
  tree.iterate({ enter: node => {
    if (node.type.isError) broken = true;
    if (node.name !== 'WhileStatement' && node.name !== 'ForStatement' && node.name !== 'DoStatement') return;
    const body = node.name === 'DoStatement' ? node.node.firstChild?.nextSibling : node.node.lastChild;
    if (!body) return;
    if (body.name === 'Block') inserts.push({ at: body.from + 1, text: '__hwLoopGuard();' });
    else { inserts.push({ at: body.from, text: '{__hwLoopGuard();' }); inserts.push({ at: body.to, text: '}' }); }
  } });
  if (broken || !inserts.length) return code;
  inserts.sort((a, b) => a.at - b.at);
  let output = loopGuard, last = 0;
  for (const insert of inserts) { output += code.slice(last, insert.at) + insert.text; last = insert.at; }
  return output + code.slice(last);
}

/**
 * State of the live editor. One instance for the whole application, so drafts, the chosen framework and the
 * undo history survive a route change; drafts and choices are also written to localStorage and survive a reload.
 */
@Injectable({ providedIn: 'root' })
export class EditorStore {
  private readonly doc = inject(DOCUMENT);
  readonly prefs = inject(Prefs);
  private readonly base = new URL('editor/', this.doc.baseURI).href;
  private readonly runtimeBase = new URL('b/', this.base).href;
  private readonly saved = this.read();

  readonly framework = signal<Framework>(this.saved.framework ?? 'react');
  readonly languages = signal<Record<Framework, Language>>({ vanilla: 'js', react: 'ts', vue: 'ts', angular: 'ts', ...this.saved.languages });
  readonly language = computed<Language>(() => this.framework() === 'angular' ? 'ts' : this.languages()[this.framework()]);
  private readonly activeFiles = signal<Record<string, string>>({});
  readonly drafts = signal<Record<string, string>>(this.saved.drafts ?? {});
  readonly example = signal<Example | null>(null);
  readonly state = signal<RunState>('idle');
  /** Detail of the last run: elapsed milliseconds when ready, the first error line when failed. */
  readonly detail = signal('');
  readonly ranEdited = signal(false);
  readonly logs = signal<LogEntry[]>([]);
  readonly hiddenLogs = signal(0);
  readonly frame = signal<FrameDocument | null>(null);
  readonly version = signal('0.2.1');
  readonly integrity = signal('');
  readonly resetTick = signal(0);
  /** CodeMirror states by document key: keeps undo history and selection across file, framework and route changes. */
  readonly editorStates = new Map<string, EditorState>();
  private readonly examples = new Map<string, Promise<Example>>();
  private runtime?: Promise<{ sandbox: any; maps: any; manifest: any }>;
  private readonly compilers = new Map<string, Promise<any>>();
  private runCount = 0;
  private started = 0;
  private watchdog?: ReturnType<typeof setTimeout>;

  /** The variant that is LOADED (framework, language, locale); it follows the selection once its example has arrived. */
  readonly variant = computed(() => { const example = this.example(); return example ? `${exampleId}/${example.framework}/${example.language}/${example.locale}` : ''; });
  readonly files = computed(() => this.example()?.order ?? []);
  readonly activeFile = computed(() => { const files = this.files(); const chosen = this.activeFiles()[this.variant()]; return chosen && files.includes(chosen) ? chosen : files[0] ?? ''; });
  readonly docKey = computed(() => this.variant() && this.activeFile() ? `${this.variant()}/${this.activeFile()}` : '');
  /** True on a page that shows the example as written (direction D's component page): drafts are neither shown nor run there. */
  readonly pristine = signal(false);
  readonly hasDraft = computed(() => { const prefix = this.variant() + '/'; return prefix.length > 1 && Object.keys(this.drafts()).some(key => key.startsWith(prefix)); });
  readonly dirty = computed(() => !this.pristine() && this.hasDraft());
  readonly packageName = computed(() => `@hawiyah/${this.framework()}`);
  readonly errorCount = computed(() => this.logs().filter(entry => entry.level === 'error').length);

  constructor() {
    effect(() => {
      const framework = this.framework(), language = this.language(), locale = this.prefs.lang();
      this.pristine();
      let stale = false;
      this.load(framework, language, locale).then(example => {
        if (stale) return;
        this.example.set(example);
        // A restored draft is not run without being asked: it may be the code that failed last time.
        untracked(() => { if (this.dirty()) { this.state.set('idle'); this.detail.set(''); this.frame.set(null); this.logs.set([]); } else void this.run(); });
      }).catch(error => { if (!stale) this.fail(String(error?.message ?? error)); });
      return () => { stale = true; };
    });
    effect(() => {
      const value = JSON.stringify({ framework: this.framework(), languages: this.languages(), drafts: this.drafts() });
      try { this.doc.defaultView?.localStorage.setItem(storageKey, value); } catch { /* storage unavailable: drafts live for this visit only */ }
    });
  }

  private read(): { framework?: Framework; languages?: Partial<Record<Framework, Language>>; drafts?: Record<string, string> } {
    try { return JSON.parse(this.doc.defaultView?.localStorage.getItem(storageKey) ?? '{}') ?? {}; } catch { return {}; }
  }
  private load(framework: Framework, language: Language, locale: string): Promise<Example> {
    const url = `${this.base}examples/${exampleId}/${framework}.${language}.${locale}.json`;
    if (!this.examples.has(url)) this.examples.set(url, fetch(url).then(response => { if (!response.ok) throw new Error(`${response.status} ${url}`); return response.json(); }));
    return this.examples.get(url)!;
  }

  setFramework(framework: Framework): void { if (frameworks.includes(framework) && framework !== this.framework()) this.framework.set(framework); }
  setLanguage(language: Language): void { if (this.framework() !== 'angular' && (language === 'js' || language === 'ts')) this.languages.update(all => ({ ...all, [this.framework()]: language })); }
  /** File names of a framework's project, known without loading it (used by the workspace tree). */
  fileNames(framework: Framework): string[] {
    const ts = framework === 'angular' || this.languages()[framework] === 'ts', x = ts ? 'ts' : 'js';
    return framework === 'vanilla' ? ['index.html', `main.${x}`, 'style.css'] : framework === 'react' ? [`App.${x}x`, `main.${x}x`, 'style.css'] : framework === 'vue' ? ['App.vue', `main.${x}`, 'style.css'] : ['app.component.ts', 'main.ts', 'style.css'];
  }
  openFile(framework: Framework, file: string): void {
    const language = framework === 'angular' ? 'ts' : this.languages()[framework];
    this.activeFiles.update(all => ({ ...all, [`${exampleId}/${framework}/${language}/${this.prefs.lang()}`]: file }));
    this.setFramework(framework);
  }
  setFile(file: string): void { if (this.files().includes(file)) this.activeFiles.update(all => ({ ...all, [this.variant()]: file })); }
  source(file: string): string { return (this.pristine() ? undefined : this.drafts()[`${this.variant()}/${file}`]) ?? this.example()?.files[file] ?? ''; }
  setDraft(key: string, text: string): void {
    const example = this.example();
    const file = key.slice(key.lastIndexOf('/') + 1);
    if (!example || this.pristine() || !key.startsWith(this.variant() + '/')) return;
    this.drafts.update(all => { const next = { ...all }; if (text === example.files[file]) delete next[key]; else next[key] = text; return next; });
  }
  /** Discard the drafts of the current framework and language only. The open file can be restored with undo. */
  reset(): void {
    const prefix = this.variant() + '/';
    this.drafts.update(all => Object.fromEntries(Object.entries(all).filter(([key]) => !key.startsWith(prefix))));
    for (const key of [...this.editorStates.keys()]) if (key.startsWith(prefix) && key !== this.docKey()) this.editorStates.delete(key);
    this.resetTick.update(tick => tick + 1);
    void this.run();
  }

  private loadRuntime() {
    this.runtime ??= (async () => {
      const [sandbox, sources, maps, manifest] = await Promise.all([
        import(/* @vite-ignore */ `${this.base}sandbox.js`),
        fetch(`${this.base}frame-sources.json`).then(response => response.json()),
        fetch(`${this.runtimeBase}importmaps.json`).then(response => response.json()),
        fetch(`${this.runtimeBase}manifest.json`).then(response => response.json()),
      ]);
      // The frame's own code is served as a file: it must not pass through this application's compiler.
      sandbox.useFrameSources(sources);
      return { sandbox, maps, manifest };
    })();
    return this.runtime;
  }
  private loadCompiler(framework: Framework) {
    if (!this.compilers.has(framework)) this.compilers.set(framework, (async () => {
      const [project, transpiler, sfc] = await Promise.all([
        import(/* @vite-ignore */ `${this.base}compilers/project.js`),
        import(/* @vite-ignore */ `${this.base}compilers/${compilerOf[framework]}.js`),
        framework === 'vue' ? import(/* @vite-ignore */ `${this.base}compilers/vue-sfc.js`) : undefined,
      ]);
      await transpiler.init();
      return { project, transpiler, sfc };
    })());
    return this.compilers.get(framework)!;
  }

  /** Build the preview document for the selected framework. Edited code is compiled here and executed only inside the frame. */
  async run(): Promise<void> {
    const example = this.example();
    if (!example) return;
    const run = ++this.runCount, edited = this.dirty();
    clearTimeout(this.watchdog);
    this.started = performance.now();
    this.state.set('running'); this.detail.set(''); this.logs.set([]); this.hiddenLogs.set(0); this.ranEdited.set(edited);
    try {
      const { sandbox, maps, manifest } = await this.loadRuntime();
      const entry = manifest.packages?.[this.packageName()];
      if (entry) { this.version.set(entry.version); this.integrity.set(entry.integrity ?? ''); }
      let compiled: any = example.compiled, host = example.host;
      if (edited) {
        const files = Object.fromEntries(example.order.map(file => [file, this.source(file)]));
        const tools = await this.loadCompiler(example.framework);
        compiled = await tools.project.compileProject({ files, entry: example.entry, format: 'esm', toolchain: { transpile: tools.transpiler.transpile, sfc: tools.sfc, lexer: tools.project.lexer } });
        compiled = { ...compiled, modules: Object.fromEntries(Object.entries(compiled.modules as Record<string, string>).map(([name, code]) => [name, guardLoops(code)])) };
        if (example.framework === 'vanilla') host = `<div id="app">${files['index.html'] ?? ''}</div>`;
      }
      if (run !== this.runCount) return;
      const map = maps[example.framework === 'angular' ? 'angular-linked-min' : `${example.framework}-min`];
      const importmap = { imports: Object.fromEntries(Object.entries(map.imports as Record<string, string>).map(([name, path]) => [name, new URL(path, this.runtimeBase).href])) };
      const t = (en: string, ar: string) => this.prefs.t(en, ar);
      const token = crypto.randomUUID();
      const srcdoc = sandbox.modulesDocument({ framework: example.framework, compiled, host, importmap, runtimeBase: this.runtimeBase,
        stylesHref: new URL('flat/styles.concat.css', this.runtimeBase).href, allowEval: example.framework === 'angular', bare: true,
        environment: { lang: this.prefs.lang(), direction: this.prefs.dir(), theme: 'dga', mode: this.prefs.mode(), density: 'comfortable' }, token, run,
        title: t('Result of the example', 'نتيجة المثال'),
        labels: { blocked: t('A resource outside the runtime directory was blocked:', 'حُجب مورد من خارج مجلد بيئة التشغيل:'), navigation: t('Navigation outside the example is not available in the result.', 'التنقل خارج المثال غير متاح في النتيجة.'),
          submitted: t('The form was submitted inside the example. No data is sent.', 'أُرسل النموذج داخل المثال، ولا تُرسل أي بيانات.'), unsupported: t('The example did not start.', 'تعذّر بدء المثال.') } });
      this.frame.set({ srcdoc, token, run });
      this.watchdog = setTimeout(() => { if (run === this.runCount && this.state() === 'running') this.fail(t('The result did not report ready within 20 seconds.', 'لم تُبلّغ النتيجة عن جاهزيتها خلال 20 ثانية.')); }, 20000);
    } catch (error: any) {
      if (run === this.runCount) this.fail(String(error?.message ?? error));
    }
  }
  private fail(text: string): void {
    clearTimeout(this.watchdog);
    const message = text.includes('LOOP_GUARD') ? this.prefs.t('A loop ran for more than 2 seconds and was stopped.', 'استمرت حلقة تكرار أكثر من ثانيتين فأُوقفت.') : text;
    this.push({ level: 'error', text: message });
    this.state.set('error'); this.detail.set(message.split('\n')[0]!.slice(0, 200));
  }
  private push(entry: LogEntry): void {
    // The log keeps the latest 200 lines and says how many earlier lines it dropped.
    this.logs.update(all => { if (all.length < 200) return [...all, entry]; this.hiddenLogs.update(count => count + 1); return [...all.slice(1), entry]; });
  }
  /** Messages from the sandboxed frame. The caller has already checked the source window. */
  onFrameMessage(data: any): number | null {
    const frame = this.frame();
    if (!frame || !data || typeof data !== 'object' || data.channel !== 'hawiyah-component-preview' || data.token !== frame.token || data.run !== frame.run) return null;
    if (data.type === 'ready') { if (this.state() === 'running') { clearTimeout(this.watchdog); this.detail.set(String(Math.round(performance.now() - this.started))); this.state.set('ready'); } }
    else if (data.type === 'error') this.fail(String(data.text ?? ''));
    else if (data.type === 'console' && ['log', 'info', 'warn', 'error'].includes(data.level)) this.push({ level: data.level, text: String(data.text ?? '') });
    else if (data.type === 'height' && Number.isFinite(data.height)) return Math.max(160, Math.min(2000, data.height));
    return null;
  }
}

