// Prebuild step of the prototype: writes the one shared example ("request form") for four frameworks,
// two source languages (JavaScript, TypeScript) and two locales, and PRECOMPILES each variant with the
// runtime spike's project compiler, so the first run of a page needs no compiler in the browser.
// Usage: node tools/build-examples.mjs <spike project dir>
import { createRequire } from 'node:module';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const spike = process.argv[2];
if (!spike) { console.error('usage: node tools/build-examples.mjs <spike project dir>'); process.exit(2); }
const require = createRequire(join(spike, 'package.json'));
const load = file => import(pathToFileURL(file).href);
const { compileProject } = await load(join(spike, 'src/project-compiler.js'));
const typescript = await load(join(spike, 'src/compilers/typescript.js'));
const sfc = require('@vue/compiler-sfc');
const { init, parse } = await load(require.resolve('es-module-lexer'));
const toolchain = { transpile: typescript.transpile, sfc, lexer: { init, parse } };
const out = join(dirname(fileURLToPath(import.meta.url)), '../public/editor/examples/request-form');
mkdirSync(out, { recursive: true });

const strings = {
  en: { name: 'Full name', hint: 'Enter the name as it appears on the national ID.', city: 'City', choose: 'Select a city', cities: ['Riyadh', 'Jeddah', 'Dammam'],
    submit: 'Submit request', done: 'Request received', body: 'The request was recorded in this example only. No data is sent.' },
  ar: { name: 'الاسم الكامل', hint: 'اكتب الاسم كما يظهر في الهوية الوطنية.', city: 'المدينة', choose: 'اختر المدينة', cities: ['الرياض', 'جدة', 'الدمام'],
    submit: 'إرسال الطلب', done: 'تم استلام الطلب', body: 'سُجّل الطلب في هذا المثال فقط، ولا تُرسل أي بيانات.' },
};
const values = ['riyadh', 'jeddah', 'dammam'];
const css = "@import '@hawiyah/styles/styles.css';\n\n/* Application styles */\nform {\n  max-inline-size: 28rem;\n}\n";
const citiesLiteral = (s, indent) => `[\n${values.map((value, i) => `${indent}  { value: '${value}', label: '${s.cities[i]}' },`).join('\n')}\n${indent}]`;

const sources = {
  vanilla(s, ts) {
    const main = ts ? 'main.ts' : 'main.js';
    return { entry: main, host: s => `<div id="app">${s}</div>`, files: {
      'index.html': `<form class="hw-stack">
  <div class="hw-field">
    <label class="hw-label" for="full-name">${s.name}</label>
    <input class="hw-input" id="full-name" name="fullName" aria-describedby="full-name-hint">
    <p class="hw-hint" id="full-name-hint">${s.hint}</p>
  </div>
  <div class="hw-field">
    <label class="hw-label" for="city">${s.city}</label>
    <select class="hw-select" id="city" name="city">
      <option value="">${s.choose}</option>
${values.map((value, i) => `      <option value="${value}">${s.cities[i]}</option>`).join('\n')}
    </select>
  </div>
  <button class="hw-button" type="submit" data-variant="primary">${s.submit}</button>
  <div class="hw-alert" data-tone="success" role="status" hidden>
    <div class="hw-alert-content">
      <strong>${s.done}</strong>
      <p>${s.body}</p>
    </div>
  </div>
</form>
`,
      [main]: ts ? `import { enhance } from '@hawiyah/vanilla';
import './style.css';

const root = document.querySelector<HTMLElement>('#app')!;
const cleanup: () => void = enhance(root);
const form = root.querySelector<HTMLFormElement>('form')!;
const alert = root.querySelector<HTMLElement>('.hw-alert')!;

form.addEventListener('submit', (event: SubmitEvent) => {
  event.preventDefault();
