window.addEventListener('pagehide', cleanup, { once: true });
`,
      'style.css': css } };
  },
  react(s, ts) {
    const app = ts ? 'App.tsx' : 'App.jsx', main = ts ? 'main.tsx' : 'main.jsx';
    return { entry: main, host: () => '<div id="app"></div>', files: {
      [app]: `import { useState } from 'react';
