    <Button type="submit">${s.submit}</Button>
    <Alert v-if="submitted" tone="success" title="${s.done}">
      <p>${s.body}</p>
    </Alert>
  </form>
</template>
`,
      [main]: `import { createApp } from 'vue';
import App from './App.vue';
import './style.css';

createApp(App).mount('#app');
`,
      'style.css': css } };
  },
  angular(s) {
    return { entry: 'main.ts', host: () => '<app-root></app-root>', files: {
      'app.component.ts': `import { Component } from '@angular/core';
import {
  HwAlertComponent,
  HwButtonDirective,
  HwSelectComponent,
  HwTextFieldComponent,
} from '@hawiyah/angular';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [HwAlertComponent, HwButtonDirective, HwSelectComponent, HwTextFieldComponent],
  template: \`
    <form class="hw-stack" (submit)="$event.preventDefault(); submitted = true">
      <hw-text-field label="${s.name}" hint="${s.hint}" name="fullName" />
      <hw-select label="${s.city}" name="city" placeholder="${s.choose}" [options]="cities" />
      <button hwButton type="submit">${s.submit}</button>
      @if (submitted) {
        <hw-alert tone="success" title="${s.done}">
          <p>${s.body}</p>
        </hw-alert>
      }
    </form>
  \`,
})
export class AppComponent {
  submitted: boolean = false;
  cities = ${citiesLiteral(s, '  ')};
}
`,
