import { bootstrapApplication } from '@angular/platform-browser';
import { AppComponent } from './app.component';
import './style.css';

bootstrapApplication(AppComponent).catch(error => console.error(error));
`,
      'style.css': css } };
  },
};

let count = 0;
for (const framework of Object.keys(sources)) for (const language of framework === 'angular' ? ['ts'] : ['js', 'ts']) for (const locale of ['ar', 'en']) {
  const project = sources[framework](strings[locale], language === 'ts');
  const host = project.host(framework === 'vanilla' ? project.files['index.html'] : '');
  const compiled = await compileProject({ files: project.files, entry: project.entry, format: 'esm', toolchain });
  writeFileSync(join(out, `${framework}.${language}.${locale}.json`), JSON.stringify({ id: 'request-form', framework, language, locale, entry: project.entry, host,
    order: Object.keys(project.files), files: project.files, compiled, compiledWith: `typescript ${typescript.version}` }));
  count++;
}
console.log(`request-form: ${count} precompiled variants`);

