// Behaviour checks of the editor prototypes against the built output. Usage: node tools/verify.cjs <dist> <port> <out.json>
const { chromium } = require('playwright');
const fs = require('node:fs'), path = require('node:path'), http = require('node:http');
const [, , dist, portArg, outFile] = process.argv; const port = Number(portArg);
const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.woff2': 'font/woff2', '.json': 'application/json', '.ico': 'image/x-icon' };
const server = http.createServer((req, res) => { const url = new URL(req.url, 'http://x'); let file = path.join(dist, decodeURIComponent(url.pathname)); if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) file = path.join(dist, 'index.html'); res.setHeader('content-type', types[path.extname(file)] || 'application/octet-stream'); res.setHeader('access-control-allow-origin', '*'); res.end(fs.readFileSync(file)); });
const results = {}; const note = (k, v) => { results[k] = v; console.log(k, '=>', typeof v === 'string' ? v : JSON.stringify(v)); };
(async () => {
  await new Promise(r => server.listen(port, '127.0.0.1', r));
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const base = `http://127.0.0.1:${port}`;
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  const errors = []; page.on('pageerror', e => errors.push(String(e).slice(0, 200)));
  const status = () => page.locator('app-editor-status [role=status]').innerText();
  const ready = async (ms = 20000) => { await page.waitForFunction(() => /Ready|Failed/.test(document.querySelector('app-editor-status [role=status]')?.textContent ?? ''), null, { timeout: ms }); return (await status()).replace(/\s+/g, ' '); };
  const frameText = async () => { const f = page.frames().find(f => f !== page.mainFrame()); return f ? (await f.locator('body').innerText()).replace(/\s+/g, ' ').slice(0, 160) : '(no frame)'; };
  const code = () => page.evaluate(() => document.querySelector('app-code-surface .surface').editorView.state.doc.toString());
  const pick = async label => { await page.locator('app-framework-switch label', { hasText: label }).click(); await page.waitForTimeout(150); };
  const replaceInCode = async (find, insert) => { await page.locator('.cm-content').click(); await page.evaluate(([find, insert]) => { const view = document.querySelector('app-code-surface .surface').editorView; const at = view.state.doc.toString().indexOf(find); if (at < 0) throw new Error('not found: ' + find); view.dispatch({ changes: { from: at, to: at + find.length, insert } }); }, [find, insert]); };

  // 1. Each framework runs its precompiled example from the published packages.
  await page.goto(`${base}/editor/a?lang=en`, { waitUntil: 'networkidle' });
  for (const fw of ['JavaScript', 'React', 'Vue', 'Angular']) {
    await pick(fw); await page.waitForTimeout(100); const s = await ready();
    note(`run.${fw}`, { status: s, pkg: (await page.locator('app-editor-status .package').innerText()).replace(/\s+/g, ' '), tabs: await page.locator('[role=tab]').allInnerTexts(), frame: await frameText(), sandbox: await page.locator('iframe').getAttribute('sandbox') });
  }
  // submit inside the frame shows the alert
  await pick('React'); await ready();
  { const f = page.frames().find(f => f !== page.mainFrame()); await f.locator('button[type=submit]').click(); await page.waitForTimeout(300); note('react.submit', await frameText()); }

  // 2. Edit + Ctrl+Enter: runs, inserts no blank line.
  for (const [fw, find, insert] of [['React', 'label="Full name"', 'label="Edited in React"'], ['JavaScript', '>Full name<', '>Edited in JavaScript<'], ['Vue', 'label="Full name"', 'label="Edited in Vue"'], ['Angular', 'label="Full name"', 'label="Edited in Angular"']]) {
    await pick(fw); await ready();
    await replaceInCode(find, insert);
    const before = await code();
    await page.locator('.cm-content').focus(); await page.keyboard.press('Control+Enter');
    await page.waitForTimeout(200);
    let s; try { s = await ready(40000); } catch (e) { s = 'timeout: ' + await status(); }
    note(`edit.${fw}`, { status: s, unchangedByShortcut: before === await code(), frame: await frameText(), resetEnabled: await page.locator('app-file-actions button').first().isEnabled() });
  }
  // 3. Loop guard: an endless loop in edited React code is stopped and the page stays usable.
  await pick('React'); await page.waitForTimeout(300);
  await replaceInCode('export default function App() {', 'export default function App() {\n  while (true) {}');
  const t0 = Date.now(); await page.locator('app-run-button button').click();
  let s3; try { s3 = await ready(15000); } catch (e) { s3 = 'timeout'; }
  note('loopGuard', { status: s3, ms: Date.now() - t0, alert: (await page.locator('app-result hw-alert').innerText().catch(() => '')).replace(/\s+/g, ' ') });
  // 4. Syntax error is reported with its text.
  await replaceInCode('while (true) {}', 'const half = <');
  await page.locator('app-run-button button').click(); await page.waitForTimeout(300);
  note('syntaxError', (await ready()).slice(0, 200));
  // 5. Drafts survive a route change and a reload; a restored draft is not run automatically.
  await page.locator('nav a', { hasText: 'C: workspace' }).click(); await page.waitForTimeout(800);
  note('draft.routeChange', { hasEdit: (await code()).includes('const half = <'), url: page.url().replace(base, '') });
  await page.reload({ waitUntil: 'networkidle' }); await page.waitForTimeout(500);
  note('draft.reload', { hasEdit: (await code()).includes('const half = <'), status: (await status()).replace(/\s+/g, ' ') });
  // tree: choose Vue / main.ts
  await page.locator('[role=treeitem][data-node="vue"]').click(); await page.waitForTimeout(500);
  await page.locator('[role=treeitem][data-node="vue:main.ts"]').click(); await page.waitForTimeout(500);
  note('c.tree', { path: await page.locator('.path').innerText(), firstLine: (await code()).split('\n')[0], selected: await page.locator('[role=treeitem][aria-selected=true]').innerText() });
  // 6. Reset discards the drafts of the current framework only.
  await page.goto(`${base}/editor/a?lang=en`, { waitUntil: 'networkidle' }); await pick('React'); await page.waitForTimeout(400);
  await page.locator('app-file-actions button', { hasText: 'Reset' }).click(); let s6 = await ready();
  await page.waitForTimeout(200);
  const store = await page.evaluate(() => Object.keys(JSON.parse(localStorage.getItem('hw-prototype-editor:v1')).drafts));
  note('reset', { status: s6, clean: !(await code()).includes('const half'), remainingDrafts: store });
  // 7. Keyboard: Tab indents, Escape then Tab leaves the editor.
  await page.locator('.cm-content').click(); await page.keyboard.press('Control+Home');
  await page.keyboard.press('Tab'); const indented = (await code()).startsWith('  import');
  await page.keyboard.press('Control+z');
  await page.keyboard.press('Escape'); await page.keyboard.press('Tab');
  note('keyboard.tab', { tabIndents: indented, afterEscTab: await page.evaluate(() => { const a = document.activeElement; return a.closest('.cm-editor') ? 'still in editor' : `${a.tagName.toLowerCase()}${a.title ? '[' + a.title + ']' : ''} ${(a.textContent || '').trim().slice(0, 30)}`; }), codeUnchanged: !(await code()).startsWith('  import') });
  // Ctrl+Enter from a toolbar control
  await page.locator('app-file-actions button', { hasText: 'Copy' }).focus(); await page.keyboard.press('Control+Enter'); await page.waitForTimeout(100);
  note('keyboard.runFromToolbar', (await status()).replace(/\s+/g, ' ').slice(0, 60)); await ready();
  // tab order of the editor section
  await page.locator('nav a').last().focus(); const order = [];
  for (let i = 0; i < 16; i++) { await page.keyboard.press('Tab'); order.push(await page.evaluate(() => { const a = document.activeElement; return a.classList.contains('cm-content') ? 'code editor' : a.tagName === 'IFRAME' ? 'result frame' : a.tagName === 'BODY' ? 'body' : (a.getAttribute('aria-label') || a.textContent || a.value || a.tagName).trim().slice(0, 28) + (a.type === 'radio' ? ' (radio)' : a.getAttribute('role') ? ` (${a.getAttribute('role')})` : ''); })); if (order.at(-1) === 'code editor') { await page.keyboard.press('Escape'); } }
  note('keyboard.order.a', order);
  // 8. Language switch (drafts of the other frameworks are cleared first, so their examples run on selection)
  await page.evaluate(() => localStorage.clear()); await page.reload({ waitUntil: 'networkidle' }); await pick('React'); await page.waitForTimeout(300); await ready();
  await page.locator('app-language-switch label', { hasText: 'JavaScript' }).click(); await page.waitForTimeout(300);
  note('language.js', { status: await ready(), tabs: await page.locator('[role=tab]').allInnerTexts(), line11: (await code()).split('\n')[10] });
  await pick('Angular'); await page.waitForTimeout(300); await ready();
  note('language.angular', { jsDisabled: await page.locator('app-language-switch input[value=js]').isDisabled(), tsChecked: await page.locator('app-language-switch input[value=ts]').isChecked() });
  await pick('React'); await page.waitForTimeout(300); await ready();
  note('language.rememberedPerFramework', await page.locator('app-language-switch input[value=js]').isChecked());
  await page.locator('app-language-switch label', { hasText: 'TypeScript' }).click(); await page.waitForTimeout(300); await ready();
  // console output reaches the log
  await replaceInCode("const cities", "console.log('hello from the example');\nconst cities");
  await page.locator('app-run-button button').click(); await page.waitForTimeout(300); await ready();
  note('log.a', (await page.locator('summary.hw-collapsible-trigger').last().innerText().catch(() => 'no log')).trim());
  await page.locator('app-file-actions button', { hasText: 'Reset' }).click(); await ready();

  // 9. B: closed by default, opens, framework tabs switch the result.
  await page.goto(`${base}/editor/b?lang=en`, { waitUntil: 'networkidle' });
  const closed = await page.locator('.cm-content').count();
  await page.locator('summary.hw-collapsible-trigger').click(); await page.waitForTimeout(400);
  await page.locator('[role=tab]', { hasText: 'Vue' }).click(); await page.waitForTimeout(300);
  note('b', { editorsWhenClosed: closed, editorsWhenOpen: await page.locator('.cm-content').count(), status: await ready(), summary: (await page.locator('summary.hw-collapsible-trigger').innerText()).trim(), firstLine: (await code()).split('\n')[0] });
  await page.reload({ waitUntil: 'networkidle' }); note('b.rememberedOpen', await page.locator('.cm-content').count());
  // 10. D: read-only page, link to the editor.
  await page.goto(`${base}/editor/d?lang=en`, { waitUntil: 'networkidle' }); await ready();
  await page.locator('.cm-content').click(); await page.keyboard.type('x');
  note('d', { readOnlyUnchanged: !(await code()).startsWith('x'), status: await status() });
  await page.locator('a', { hasText: 'Open in the editor' }).click(); await page.waitForTimeout(800);
  note('d.workspace', { url: page.url().replace(base, ''), h1: await page.locator('h1').innerText(), editable: await page.locator('.cm-content[contenteditable=true]').count(), log: await page.locator('app-log-panel').count() });

  // 11. Layout measurements at 1440x900: code area height and controls height (top of the editor shell to top of the code).
  const measure = async route => { await page.goto(`${base}${route}${route.includes('?') ? '&' : '?'}lang=en`, { waitUntil: 'networkidle' }); await page.waitForTimeout(500); return page.evaluate(() => { const cm = document.querySelector('.cm-editor')?.getBoundingClientRect(); const shell = (document.querySelector('.code hw-collapsible') ?? document.querySelector('.source') ?? document.querySelector('.ed-shell')).getBoundingClientRect(); const frame = document.querySelector('iframe').getBoundingClientRect(); return cm ? { codeH: Math.round(cm.height), codeW: Math.round(cm.width), controlsAboveCode: Math.round(cm.top - shell.top), resultW: Math.round(frame.width), codeTopInPage: Math.round(cm.top + scrollY), overflowX: document.documentElement.scrollWidth - innerWidth } : null; }); };
  for (const route of ['/editor/a', '/editor/b?code=open', '/editor/c', '/editor/d', '/editor/d/workspace']) note(`measure.1440${route}`, await measure(route));
  await context.close();

  // 12. Narrow widths and independent direction.
  for (const [w, h] of [[390, 844], [320, 640]]) for (const q of ['lang=ar', 'lang=en', 'lang=en&dir=rtl', 'lang=ar&dir=ltr']) {
    const c = await browser.newContext({ viewport: { width: w, height: h } }); const p = await c.newPage(); const row = {};
    for (const route of ['/editor/a', '/editor/b?code=open', '/editor/c', '/editor/d', '/editor/d/workspace']) { await p.goto(`${base}${route}${route.includes('?') ? '&' : '?'}${q}`, { waitUntil: 'networkidle' }); await p.waitForTimeout(300); row[route] = await p.evaluate(() => { const cm = document.querySelector('.cm-editor')?.getBoundingClientRect(); const shell = (document.querySelector('.code hw-collapsible') ?? document.querySelector('.source') ?? document.querySelector('.ed-shell')).getBoundingClientRect(); return `overflowX=${document.documentElement.scrollWidth - document.documentElement.clientWidth} dir=${document.documentElement.dir} codeDir=${getComputedStyle(document.querySelector('.cm-content')).direction} code=${Math.round(cm.width)}x${Math.round(cm.height)} above=${Math.round(cm.top - shell.top)}`; }); }
    note(`narrow.${w}.${q}`, row); await c.close();
  }
  note('pageErrors', errors);
  fs.writeFileSync(outFile, JSON.stringify(results, null, 1));
  await browser.close(); server.close();
})().catch(e => { console.error('VERIFY FAILED', e); fs.writeFileSync(outFile, JSON.stringify(results, null, 1)); process.exit(1); });

